CREATE TABLE public.tutor_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL DEFAULT 'New conversation', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tutor_threads TO authenticated;
GRANT ALL ON public.tutor_threads TO service_role;
ALTER TABLE public.tutor_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_threads ON public.tutor_threads FOR ALL TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE TABLE public.tutor_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.tutor_threads(id) ON DELETE CASCADE, user_id uuid NOT NULL DEFAULT auth.uid(), message_id text NOT NULL, message jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id,message_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tutor_messages TO authenticated;
GRANT ALL ON public.tutor_messages TO service_role;
ALTER TABLE public.tutor_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_messages ON public.tutor_messages FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.tutor_threads WHERE id=thread_id AND user_id=auth.uid()));
CREATE TABLE public.study_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), subject text NOT NULL, duration integer NOT NULL, hyper boolean NOT NULL DEFAULT false, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
GRANT SELECT, INSERT ON public.study_sessions TO authenticated;
GRANT ALL ON public.study_sessions TO service_role;
ALTER TABLE public.study_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_sessions_read ON public.study_sessions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_sessions_start ON public.study_sessions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND completed_at IS NULL AND duration IN(300,900,1500,2700,3600));
CREATE TABLE public.theme_redemptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), theme text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,theme));
GRANT SELECT ON public.theme_redemptions TO authenticated;
GRANT ALL ON public.theme_redemptions TO service_role;
ALTER TABLE public.theme_redemptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_themes ON public.theme_redemptions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.complete_study_session(session_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.study_sessions SET completed_at=now() WHERE id=session_id AND user_id=auth.uid() AND completed_at IS NULL AND now() >= started_at + make_interval(secs=>duration); IF NOT FOUND THEN RAISE EXCEPTION 'Session is not yet complete'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.complete_study_session(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.complete_study_session(uuid) TO authenticated;
CREATE FUNCTION public.redeem_study_theme(chosen_theme text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE earned integer; spent integer; BEGIN IF auth.uid() IS NULL OR chosen_theme NOT IN('mint','rose') THEN RAISE EXCEPTION 'Invalid theme'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT count(*) INTO earned FROM public.study_sessions WHERE user_id=auth.uid() AND hyper AND completed_at IS NOT NULL; SELECT count(*)*5 INTO spent FROM public.theme_redemptions WHERE user_id=auth.uid(); IF earned-spent < 5 THEN RAISE EXCEPTION 'Complete more hyper focus sessions to earn 5 points'; END IF; INSERT INTO public.theme_redemptions(user_id,theme) VALUES(auth.uid(),chosen_theme); END; $$;
REVOKE ALL ON FUNCTION public.redeem_study_theme(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.redeem_study_theme(text) TO authenticated;